  let firstChannelId = null;

  state.categories.forEach((cat, catIdx) => {
    const catBlock = document.createElement("div");
    catBlock.className = "discord-category-block";
    catBlock.style.display = "flex";
    catBlock.style.flexDirection = "column";
    catBlock.style.gap = "0.25rem";

    // Cabeçalho da Categoria
    const catHeader = document.createElement("div");
    catHeader.className = "discord-category-header";
    catHeader.style.fontSize = "0.76rem";
    catHeader.style.fontWeight = "700";
    catHeader.style.color = "#94A3B8";
    catHeader.style.letterSpacing = "0.5px";
    catHeader.style.padding = "0.4rem 0.2rem 0.2rem";
    catHeader.style.cursor = "default";
    catHeader.textContent = cat.title;
    catBlock.appendChild(catHeader);

    // Canais da Categoria
    cat.channels.forEach(ch => {
      if (!firstChannelId) firstChannelId = ch.id;

      const chBtn = document.createElement("button");
      chBtn.className = `sidebar-btn discord-channel-btn ${state.activeChannelId === ch.id ? 'active' : ''}`;
      chBtn.style.paddingLeft = "0.9rem";
      chBtn.style.fontSize = "0.82rem";
      chBtn.style.display = "flex";
      chBtn.style.alignItems = "center";
      chBtn.style.gap = "0.4rem";
      chBtn.innerHTML = `<span>${ch.title}</span>`;
      chBtn.onclick = () => loadChannel(ch.id);
      catBlock.appendChild(chBtn);
    });

    container.appendChild(catBlock);
  });

