  res.on('end', () => {
    const json = JSON.parse(data);
    let ok = 0;
    json.categories.forEach(cat => {
      cat.channels.forEach(ch => {
        const out = parseMarkdownFn(ch.content_markdown);
        if (out && out.length > 0) ok++;
      });
    });
    console.log('Successfully parsed ' + ok + ' of 20 lessons without errors!');
  });
});
